42	/// KONSOLIDIERUNG (I-B.3, 2026-06-04, User-Fork „voll auf axis_stats[19][8]"): formatiert den EINEN konsolidierten
43	/// Observer-POD als result_ingest-Zeile = binary_id + die VOLLE Matrix: axis_stats[19][8] (152) + seg_ns[19] (19)
44	/// + Meta (observable_axis_count, tier_fill_level, filled_axis_count, batches_measured) = 175 Felder. EXAKT das von
45	/// ingest_result_line erwartete Format → Round-Trip-Garant (Cluster: perm_runner→Zeile→ingest→Baum-NodeValue).
46	/// MAJOR-MESS-09 (Mess-Validität, Audit A1): binary_id ist das ERSTE ';'-Feld der result_ingest-Zeile (= Baum-Key).
47	/// Enthielte es selbst ein ';' oder einen Zeilenumbruch, verschöbe es beim Re-Parse ALLE 175 nachfolgenden Felder
48	/// (axis_stats/seg_ns landeten im falschen Slot) — eine stille Mess-Verfälschung. Da der Wert ein Datei-Stem/Label ist
49	/// (keine ';'/Newline by-construction), lehnen wir einen verletzenden Wert HART ab (leere Zeile → ingest verwirft sie),
50	/// statt zu escapen: das hält das ';'-Wire-Format 1:1 feldzählbar (exaktes ==176, s. ingest_result_line).
51	[[nodiscard]] inline bool binary_id_is_wire_safe(std::string_view binary_id) noexcept {
52	    return !binary_id.empty() && binary_id.find(';') == std::string_view::npos &&
53	           binary_id.find('\n') == std::string_view::npos && binary_id.find('\r') == std::string_view::npos;
54	}
55	
56	[[nodiscard]] inline std::string format_perm_result(std::string const&                          binary_id,
57	                                                    anatomy::ComdareTierObserverSnapshot const& s) {
58	    if (!binary_id_is_wire_safe(binary_id)) return std::string{}; // ungültige ID → leere Zeile (ingest verwirft)
59	    std::string out  = binary_id;
60	    auto        addu = [&](std::uint64_t v) {
61	        out += ';';
62	        out += std::to_string(v);
63	    };
64	    auto addi = [&](std::int64_t v) {
65	        out += ';';
66	        out += std::to_string(v);
67	    };
68	    for (std::size_t t = 0; t < 19; ++t)
69	        for (std::size_t f = 0; f < 8; ++f) addu(s.axis_stats[t][f]);
70	    for (std::size_t t = 0; t < 19; ++t) addi(s.seg_ns[t]);
71	    addu(s.observable_axis_count);
72	    addu(s.tier_fill_level);
73	    addu(s.filled_axis_count);
74	    addu(s.batches_measured);
75	    // P-MD3 (2026-06-18): die 2 additiven Coverage-Versöhnungs-Meta-Felder hinten anhängen → Wire-Format 175→177
76	    // Felder (binary_id + 177 = 178 total). Round-Trip-Garant mit ingest_result_line (exaktes ==178).
77	    addi(s.seg_framework_ns);
78	    addi(s.seg_run_total_ns);
79	    return out;
80	}
