82	// ── GOAL-M/L1 (2026-06-12): per-Interface-Funktions-Latenzen für die Konfig×Tier-Auswertung ───────────
83	/// Aggregat der getimten Latenzen EINER Interface-Funktion (Op-Art) dieser Messung: Sample-Zahl +
84	/// Nearest-Rank-Perzentile (konsistent zu serialize_workload_run_results_csv). n==0 = Op-Art im Profil
85	/// nicht vorhanden (bzw. Scan auf nicht-scanbarem Tier ehrlich übersprungen).
86	struct OpKindLatency {
87	    std::uint64_t n      = 0;
88	    std::int64_t  p50_ns = 0;
89	    std::int64_t  p99_ns = 0;
90	};
91	/// Single-Source der Op-Art-Reihenfolge (CSV-Spalten ↔ PermResult::op_lat ↔ WorkloadRunResult-Vektoren).
92	inline constexpr std::array<char const*, 6> kOpKindNames{"insert", "lookup", "erase", "clear", "scan", "rmw"};
93	
94	// ── (B): Ergebnis einer Mess-Last (result_ingest-Zeile + die Host-Wall-Clock) ─────────────────────────
95	struct PermResult {
96	    std::string   line;         // result_ingest-Zeile (binary_id + volle Observer-Matrix)
97	    std::int64_t  total_ns = 0; // (B) steady_clock-Wall-Clock-Summe ALLER getimten Ops DIESER Messung
98	    std::uint64_t n_ops    = 0; // Eingabe-n_ops (Skala des Profils)
99	    // GOAL-M1.1 (Audit K2): Anzahl der TATSÄCHLICH getimten Einzel-Ops → ns_per_op = total_ns/timed_ops.
100	    // Workload-Pfad: Σ der per-Op-Art-Samples (deckt Scan-Skips ehrlich ab); Legacy-Pfad: 2*n_ops
101	    // (n_ops Inserts + n_ops Lookups). Ersetzt den fehlerhaften fixen 2*n_ops-Divisor für Profil-Zeilen.
102	    std::uint64_t timed_ops = 0;
103	    // GOAL-L1: per-Interface-Funktions-Latenzen (Reihenfolge kOpKindNames) — die z-Achsen-Quelle der
104	    // 3D-Diagramme (Verarbeitungsdauer je Testdatensatz-Operation, getrennt je Interface-Funktion).
105	    std::array<OpKindLatency, 6> op_lat{};
106	    // KONSOLIDIERUNG (I1): der EINE konsolidierte Observer-Snapshot (axis_stats[19][8] + seg_ns[19]/Pfad B + Meta)
107	    // aus dem EINEN tier_observe. Trägt Observer-Stats UND das Pfad-B-Per-Achsen-Timing (reale Komposition) in EINEM
108	    // POD — die maßgebliche CSV-Quelle.
109	    anatomy::ComdareTierObserverSnapshot unified{};
110	    bool                                 unified_real = false;
111	    // #156-De-Risk (2026-06-20): die HW-Performance-Counter (PMC) DIESER Messung = Delta über den getimten Batch.
112	    // EINMAL pro Treiber-Lauf via make_pmc_source() erzeugt (KEIN Hot-Loop-Overhead), begin() unmittelbar VOR
113	    // t0=steady_clock, end() unmittelbar NACH t1. Default = PmcCounters{} (alle 0, available=false) → lokal mit
114	    // NullPmcSource (COMDARE_ENABLE_PMC=OFF) ehrlich 0/available=0; mit Intel-PCM (Montag, Linux/Win+Treiber) real.
115	    builder::PmcCounters pmc{};
116	    // Achse 2 (INC-1): Lastprofil-Metadaten + Mess-GÜLTIGKEIT.
117	    std::string profile_name{};          // Lastprofil-Name (z.B. "YCSB_C_read_only"); leer = alter fixer Workload
118	    bool        two_phase_valid = false; // Zwei-Phasen-Cache-Warmup aktiv+empirisch-exakt → Messung GÜLTIG
119	                                         // (false = ungültig: KEINE stille Kalt-Messung als gültiges Ergebnis)
120	    // (Audit K9 / V5-I4) Konformitäts-Gate-Ergebnis (import→GATE→messen): die Hülle wurde VOR der Messung gegen
121	    // std::map<uint64,uint64> als Oracle getrieben. conformance_passed=false ⇒ NICHT std::map-konform → es gibt
122	    // KEINE gültige Performance-Zeile (gated≠gültig; der Mess-Block wird übersprungen, Zeile = genullte Matrix).
123	    // Reist host-seitig (wie two_phase_valid), NICHT im 175-Feld-Wire-Format → Round-Trip unverändert.
124	    bool          conformance_passed       = false; ///< cases_total>0 && alle Zusicherungen bestanden
125	    std::uint64_t conformance_cases_total  = 0;     ///< Anzahl geprüfter Einzel-Zusicherungen (0 = Gate nicht gelaufen)
126	    std::uint64_t conformance_cases_passed = 0;     ///< davon bestanden
127	    std::uint64_t conformance_first_fail   = 0;     ///< 1-basierter Index der ersten Verletzung (0 = keine)
128	};
129	
130	// ── (Audit K9 / V5-I4) Konformitäts-Gate VOR der Messung — Reihenfolge bindend: import → GATE → (nur bei pass) messen ──
131	/// Treibt das funktionale IDriveableTier-Sub-Interface (IMMER vorhanden, auch in Release-/funktional-only-DLLs) gegen
132	/// std::map<uint64,uint64> als Oracle (Randfälle RF1–7 + 2000 deterministische Zufalls-Ops). Schreibt die Konformitäts-
133	/// Quoten in r. passed()=false ⇒ die Hülle ist NICHT std::map-konform → der Aufrufer überspringt die Messung.
134	inline void apply_conformance_gate_(anatomy::IDriveableTier& tier, PermResult& r) noexcept {
135	    auto const cg              = ::comdare::cache_engine::builder::pruef_dock::run_conformance_gate(tier);
136	    r.conformance_cases_total  = cg.cases_total;
137	    r.conformance_cases_passed = cg.cases_passed;
138	    r.conformance_first_fail   = cg.first_fail;
139	    r.conformance_passed       = cg.passed();
140	}
141	/// Gate-Fehlschlag: ehrliche genullte Matrix-Zeile, KEINE Performance-Messung (gated≠gültig). two_phase_valid/unified_real
142	/// bleiben false → der Iterator emittiert KEINE gültige Mess-Zeile für eine nicht-konforme Hülle.
143	[[nodiscard]] inline PermResult gate_failed_result_(PermResult r, std::string const& binary_id) {
144	    r.two_phase_valid = false;
145	    r.unified_real    = false;
146	    r.line            = format_perm_result(binary_id, r.unified); // genullter POD → ehrlich „nicht gemessen"
147	    return r;
148	}
149	
150	/// (A)+(B) Treibt ein geladenes IObservableTier (SearchAlgorithm-Mess-Pfad): ZUERST tier_clear() (frischer
151	/// Zustand → kein kumulatives Artefakt), pre-Observe (Baseline der absoluten Zähler), n_ops insert + n_ops
152	/// lookup UNTER steady_clock-Messung (total_ns), post-Observe, und bildet die result_ingest-Zeile aus dem
153	/// DELTA (post − pre) der getriebenen Zähler. Der host-/cluster-seitige Unikat-Mess-Lauf je Binary.
154	/// #156-De-Risk (2026-06-20): `pmc` ist die EINE, vom Aufrufer pro Treiber-Lauf via make_pmc_source() erzeugte
155	/// HW-Counter-Quelle (Strategy: NullPmcSource/WindowsPcmPmcSource hinter IPmcSource). nullptr = kein PMC (Default
156	/// → r.pmc bleibt 0/available=false, exakt das alte Verhalten; KEIN Mess-Overhead). begin()/end() klammern NUR
157	/// den getimten Batch (NICHT je Op), parallel zur steady_clock-Wall-Clock.
158	[[nodiscard]] inline PermResult run_observable_perm(anatomy::IObservableTier& tier, std::string const& binary_id,
159	                                                    std::uint64_t n_ops, builder::IPmcSource* pmc = nullptr) {
160	    PermResult r;
161	    // (Audit K9 / V5-I4) import → GATE → (nur bei pass) messen: nicht-std::map-konforme Hüllen erzeugen KEINE gültige
162	    // Performance-Zeile. Das Gate leert das Tier selbst (RF1+RF7) → der folgende tier_clear() ist idempotent.
163	    apply_conformance_gate_(tier, r);
164	    if (!r.conformance_passed) return gate_failed_result_(std::move(r), binary_id);
165	
166	    // (A) Reset: frischer Datenstruktur-Zustand. tier_clear() ruft jetzt container_algorithm_.reset() (I-B.1) → auch die
167	    // T0-search-Statistik wird je Messung genullt → KEIN post−pre-Delta mehr nötig (axis_stats warmup-frei aus
168	    // EINEM Post-Observe). Die result_ingest-Zeile entsteht unten aus dem EINEN konsolidierten POD (volle Matrix).
169	    tier.tier_clear();
170	
171	    // (B) Gesamt-Wall-Clock um die GANZE Mess-Last (insert + lookup).
172	    // #156-De-Risk: PMC begin() UNMITTELBAR VOR t0, end() UNMITTELBAR NACH t1 → das Counter-Delta deckt exakt den
173	    // getimten Batch (kein Hot-Loop-Overhead). pmc==nullptr → r.pmc bleibt Default (0/available=false).
174	    if (pmc != nullptr) pmc->begin();
175	    auto const t0 = std::chrono::steady_clock::now();
176	    for (std::uint64_t i = 0; i < n_ops; ++i) (void)tier.tier_insert(i, i * 7u + 1u);
177	    for (std::uint64_t i = 0; i < n_ops; ++i) {
178	        std::uint64_t v = 0;
179	        (void)tier.tier_lookup(i, &v);
180	    }
181	    auto const t1 = std::chrono::steady_clock::now();
182	    if (pmc != nullptr) r.pmc = pmc->end();
183	
184	    r.total_ns  = std::chrono::duration_cast<std::chrono::nanoseconds>(t1 - t0).count();
185	    r.n_ops     = n_ops;
186	    r.timed_ops = 2u * n_ops; // GOAL-M1.1: Legacy-Fix-Workload = n_ops Inserts + n_ops Lookups getimt
187	    // KONSOLIDIERUNG (I1): den EINEN konsolidierten Snapshot ziehen (axis_stats + Pfad-B-seg_ns in EINEM POD).
188	    // Der EINE tier_observe hält intern die fixe Q1-Sequenz (axis_stats-READ → seg_ns-Timing → per-op-Reset) → keine
189	    // Doppelzählung. Da tier_clear() jetzt container_algorithm_.reset() ruft, sind ALLE 19 Achsen pro Zeile warmup-frei
190	    // (kein post−pre-Delta nötig): die auto-gekoppelten Instanz-Organe (T1/T2/T3/T7/T8/T10/T17/T18) werden in
191	    // tier_clear() statistik-genullt, die Scan-Achsen (T4/T5/T9/T11..T16) sind in fill_observer_v3 idempotent
192	    // (reset()+scan je Observe), T0 search_algo + T6 allocator werden über container_algorithm_.reset() frisch.
193	    tier.tier_observe(&r.unified);
194	    r.unified_real = true;
195	    // KONSOLIDIERUNG (I-B.3): die result_ingest-Zeile aus dem EINEN POD = volle Matrix (axis_stats + seg_ns + Meta).
196	    r.line = format_perm_result(binary_id, r.unified);
197	    return r;
198	}
199	
200	// ── Achse 2 (INC-1): Lastprofil-Mess-Lauf über den BEREITS implementierten Op-Skript-Runner (generischer CS-Interpreter über den flachen Op-Vektor — KEIN GoF-Interpreter mit Grammatik/AST) ──
201	namespace wd  = ::comdare::cache_engine::builder::workload_driver;
